/* Generated from themes/arcade.json. Do not edit; run pnpm tokens:build.
   The arcade theme on its own, for a consumer installing @gamestage/theme-arcade.
   Needs gamestage-tokens.css for the values it does not override, and its own
   font item for the families it names. */

@layer gs.base, gs.context, gs.theme;

@layer gs.theme {
  [data-gs-theme="arcade"] {
  --gs-color-background: linear-gradient(180deg,oklch(0.40 0.16 262),oklch(0.26 0.13 270));
  --gs-color-surface: linear-gradient(180deg,oklch(0.50 0.17 256),oklch(0.42 0.17 264));
  --gs-color-surface-raised: linear-gradient(180deg,oklch(0.64 0.15 242),oklch(0.50 0.17 258));
  --gs-color-edge: oklch(0.20 0.09 272);
  --gs-color-edge-high: oklch(0.80 0.10 228);
  --gs-color-ink: #ffffff;
  --gs-color-ink-secondary: oklch(0.88 0.05 240);
  --gs-color-muted: oklch(0.74 0.08 250);
  --gs-color-interactive: linear-gradient(180deg,oklch(0.87 0.17 82),oklch(0.72 0.19 52));
  --gs-color-interactive-hover: linear-gradient(180deg,oklch(0.91 0.16 84),oklch(0.77 0.18 54));
  --gs-color-interactive-base: oklch(0.50 0.16 45);
  --gs-color-selected: oklch(0.86 0.15 192);
  --gs-color-positive: linear-gradient(180deg,oklch(0.88 0.17 162),oklch(0.72 0.18 155));
  --gs-color-negative: linear-gradient(180deg,oklch(0.74 0.20 22),oklch(0.60 0.22 26));
  --gs-color-warning: oklch(0.82 0.18 62);
  --gs-color-reward: linear-gradient(180deg,oklch(0.92 0.15 96),oklch(0.80 0.18 76));
  --gs-color-player: oklch(0.86 0.15 192);
  --gs-color-opponent: oklch(0.72 0.22 330);
  --gs-color-disabled: oklch(0.38 0.06 265);
  --gs-color-disabled-ink: oklch(0.66 0.05 260);
  --gs-color-on-accent: oklch(0.22 0.09 272);
  --gs-color-on-bright: oklch(0.22 0.09 272);
  --gs-stroke-control: 3px;
  --gs-type-font-family-display: Bungee, Unbounded, system-ui, sans-serif;
  --gs-type-action-font-family: var(--gs-type-font-family-interface);
  --gs-type-action-font-family-primary: var(--gs-type-font-family-display);
  --gs-type-action-font-size: 19px;
  --gs-type-action-font-weight: 600;
  --gs-type-action-font-weight-primary: 400;
  --gs-type-action-text-transform-primary: uppercase;
  --gs-type-action-letter-spacing: 0.02em;
  --gs-type-display-shadow: 0 3px 0 var(--gs-color-edge);
  --gs-type-stat-font-family: var(--gs-type-font-family-display);
  --gs-type-stat-font-size: 22px;
  --gs-type-stat-font-weight: 400;
  --gs-type-score-font-family: var(--gs-type-font-family-display);
  --gs-type-score-font-size: 36px;
  --gs-type-score-font-weight: 400;
  --gs-type-score-font-variant-numeric: tabular-nums;
  --gs-type-display-font-family: var(--gs-type-font-family-display);
  --gs-type-display-font-size: 48px;
  --gs-type-display-font-weight: 400;
  --gs-depth-style: offset;
  --gs-depth-styles-offset-pressable: inset 0 1px 0 rgba(255,255,255,.3), 0 var(--gs-press-travel) 0 var(--gs-color-interactive-base);
  --gs-depth-styles-squeeze-pressable: 0 0 0 var(--gs-stroke-control) var(--gs-color-edge);
  --gs-depth-styles-squeeze-pressed: 0 0 0 var(--gs-stroke-selected) var(--gs-color-interactive);
  --gs-depth-styles-glow-pressable: 0 0 0 var(--gs-stroke-control) var(--gs-color-edge-high);
  --gs-depth-styles-glow-pressed: 0 0 0 var(--gs-stroke-selected) var(--gs-color-interactive);
  --gs-depth-raised: inset 0 1px 0 var(--gs-color-edge-high), 0 4px 12px rgba(0,0,0,.5);
  --gs-depth-pressable: inset 0 1px 0 rgba(255,255,255,.3), 0 var(--gs-press-travel) 0 var(--gs-color-interactive-base);
  --gs-depth-reward: 0 0 0 3px var(--gs-color-background), 0 0 0 5px var(--gs-color-reward), 0 0 28px oklch(0.87 0.17 92 / .45);
  --gs-type-stat-font-family: var(--gs-type-font-family-display);
  --gs-type-score-font-family: var(--gs-type-font-family-display);
  --gs-type-display-font-family: var(--gs-type-font-family-display);
  }
}
